(function(){
'use strict';
const A=window.AstroCore, KEY='astral-atlas-records-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cities=[
['台北市','Taipei',25.033,121.5654,'Asia/Taipei'],['新北市','New Taipei',25.0169,121.4628,'Asia/Taipei'],['基隆市','Keelung',25.1276,121.7392,'Asia/Taipei'],['桃園市','Taoyuan',24.9936,121.301,'Asia/Taipei'],['新竹市','Hsinchu',24.8039,120.9647,'Asia/Taipei'],['苗栗市','Miaoli',24.5602,120.8214,'Asia/Taipei'],['台中市','Taichung',24.1477,120.6736,'Asia/Taipei'],['彰化市','Changhua',24.0518,120.5161,'Asia/Taipei'],['南投市','Nantou',23.9099,120.6838,'Asia/Taipei'],['雲林斗六','Douliu',23.7092,120.5439,'Asia/Taipei'],['嘉義市','Chiayi',23.4801,120.4491,'Asia/Taipei'],['台南市','Tainan',22.9997,120.227,'Asia/Taipei'],['高雄市','Kaohsiung',22.6273,120.3014,'Asia/Taipei'],['屏東市','Pingtung',22.6761,120.4942,'Asia/Taipei'],['宜蘭市','Yilan',24.757,121.753,'Asia/Taipei'],['花蓮市','Hualien',23.9872,121.6015,'Asia/Taipei'],['台東市','Taitung',22.7583,121.1444,'Asia/Taipei'],['澎湖馬公','Magong',23.5655,119.5662,'Asia/Taipei'],['金門金城','Jincheng',24.4328,118.3171,'Asia/Taipei'],['香港','Hong Kong',22.3193,114.1694,'Asia/Hong_Kong'],['澳門','Macau',22.1987,113.5439,'Asia/Macau'],['東京','Tokyo',35.6762,139.6503,'Asia/Tokyo'],['大阪','Osaka',34.6937,135.5023,'Asia/Tokyo'],['首爾','Seoul',37.5665,126.978,'Asia/Seoul'],['新加坡','Singapore',1.3521,103.8198,'Asia/Singapore'],['北京','Beijing',39.9042,116.4074,'Asia/Shanghai'],['上海','Shanghai',31.2304,121.4737,'Asia/Shanghai'],['倫敦','London',51.5072,-0.1276,'Europe/London'],['巴黎','Paris',48.8566,2.3522,'Europe/Paris'],['紐約','New York',40.7128,-74.006,'America/New_York'],['洛杉磯','Los Angeles',34.0522,-118.2437,'America/Los_Angeles'],['舊金山','San Francisco',37.7749,-122.4194,'America/Los_Angeles'],['芝加哥','Chicago',41.8781,-87.6298,'America/Chicago'],['溫哥華','Vancouver',49.2827,-123.1207,'America/Vancouver'],['雪梨','Sydney',-33.8688,151.2093,'Australia/Sydney'],['墨爾本','Melbourne',-37.8136,144.9631,'Australia/Melbourne']
];
const nav=[['home','✧','首頁'],['chart','☼','我的星盤'],['trend','♃','流年趨勢'],['signs','✳','十二星座'],['records','☾','占星紀錄']];
const state={view:'home',chart:null,currentId:null,year:new Date().getFullYear(),records:load(),events:null,install:null};
function load(){try{let data=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(data)?data:[]}catch(e){return []}}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state.records));return true}catch(e){toast('儲存失敗，請確認裝置儲存空間');return false}}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2600)}
function navMarkup(){return nav.map(([view,icon,label])=>`<a href="#${view}" class="nav-link ${state.view===view?'active':''}" data-view="${view}" ${state.view===view?'aria-current="page"':''}><span class="nav-icon">${icon}</span><span>${label}</span></a>`).join('')}
function updateNav(){ $('#side-nav').innerHTML=navMarkup();$('#mobile-nav').innerHTML=navMarkup();$('#breadcrumb').textContent=({home:'探索你的星空',chart:'我的星盤',trend:'流年趨勢',signs:'十二星座',records:'占星紀錄'})[state.view]||'探索你的星空';}
function view(v){state.view=v;state.events=null;updateNav(); render();window.scrollTo({top:0,behavior:'instant'});}
function section(en,title,sub='',action=''){return `<div class="section-head"><div><span class="eyebrow">${en}</span><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;}
function pagehead(en,title,sub,actions=''){return `<div class="page-head"><div><span class="eyebrow">${en}</span><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function signCard(s){return `<button class="sign-card" data-action="sign" data-id="${s.id}" aria-label="認識${s.name}"><img src="./assets/${s.id}.webp" alt="${s.name}神話角色插圖" loading="lazy"><span class="sign-card-info"><span class="glyph">${s.glyph}</span><strong>${s.name}</strong><small>${s.id}</small></span></button>`;}
function home(){return `<section class="hero"><div class="hero-art"></div><div class="hero-seal"></div><div class="hero-copy"><div class="eyebrow">✦ &nbsp; A MAP OF YOUR INNER UNIVERSE</div><h1>讀懂星空，<br><em>也讀懂自己。</em></h1><p>在出生那一刻，星辰為你描繪了一張獨一無二的地圖。循著它，展開一場關於自己的探索。</p><div class="actions"><button class="btn btn-primary" data-action="new-chart">✧ &nbsp; 繪製我的星盤 <span>→</span></button><button class="btn btn-muted" data-view="signs">探索十二星座</button></div></div></section>
<div class="intro-strip"><div class="intro-item"><span class="intro-icon">☼</span><div><strong>專屬本命星盤</strong><small>看見你的星象藍圖</small></div></div><div class="intro-item"><span class="intro-icon">✧</span><div><strong>流年星象探索</strong><small>發現每個階段的主題</small></div></div><div class="intro-item"><span class="intro-icon">☾</span><div><strong>你的資料，你作主</strong><small>紀錄只留在這台裝置</small></div></div></div>
<section class="home-gallery">${section('THE ZODIAC COLLECTION','遇見十二星座','每一種星座，都是一個獨特的故事。','<button class="text-link" data-view="signs">探索全部星座 &nbsp; →</button>')}<div class="sign-grid">${A.SIGNS.slice(0,6).map(signCard).join('')}</div></section>`;}
function form(){const d=state.chart?.input||{};const city=d.city||'台北市';return `${pagehead('YOUR NATAL CHART','繪製你的本命星盤','輸入出生資料，讓星盤呈現你出生時刻的星象位置。資料只在這台裝置上計算與儲存。')}
<div class="form-layout"><form class="panel form-panel" id="birth-form"><h2 class="panel-title">你的出生資訊</h2><p class="panel-sub">出生時間和地點會影響上升星座與十二宮位置。</p><div class="form-grid">
<div class="field full"><label for="name">稱呼</label><input id="name" name="name" maxlength="40" value="${esc(d.name||'')}" placeholder="例如：小新" required></div>
<div class="field"><label for="date">出生日期</label><input id="date" name="date" type="date" min="1900-01-01" max="2050-12-31" value="${esc(d.date||'')}" required></div>
<div class="field"><label for="time">出生時間</label><input id="time" name="time" type="time" value="${esc(d.time||'')}" required><small>請使用出生地當地時間；時間不確定時，宮位與上升點可能不準確。</small></div>
<div class="field full"><label for="city">出生地</label><select id="city" name="city">${cities.map(c=>`<option value="${esc(c[0])}" ${c[0]===city?'selected':''}>${esc(c[0])}・${c[1]}</option>`).join('')}<option value="custom" ${city==='custom'?'selected':''}>其他地點（自行輸入座標與時區）</option></select><small>可使用清單中的城市，或選「其他地點」輸入更精確座標。</small></div>
<div class="field"><label for="lat">緯度</label><input type="number" name="lat" id="lat" step="any" min="-65.9999" max="65.9999" value="${esc(d.lat??25.033)}" required><small>北緯為正；目前支援 −66° 至 66° 之間。</small></div>
<div class="field"><label for="lon">經度</label><input type="number" name="lon" id="lon" step="any" min="-180" max="180" value="${esc(d.lon??121.5654)}" required><small>東經為正，例如台北 121.5654。</small></div>
<div class="field"><label for="zone">出生地時區</label><input name="zone" id="zone" value="${esc(d.zone||'Asia/Taipei')}" placeholder="Asia/Taipei" required><small>使用 IANA 時區，依裝置資料處理歷史時差與夏令時間。</small></div>
<div class="field"><label for="houseSystem">宮位系統</label><select name="houseSystem" id="houseSystem"><option value="equal" ${d.houseSystem!=='whole'?'selected':''}>等宮制 Equal House</option><option value="whole" ${d.houseSystem==='whole'?'selected':''}>整宮制 Whole Sign</option></select><small>等宮從上升點起算；整宮從上升星座的 0° 起算。</small></div>
<div class="field full"><label for="dstChoice">夏令時間重複時段</label><select name="dstChoice" id="dstChoice"><option value="earlier" ${d.dstChoice!=='later'?'selected':''}>優先選擇較早的實際時間</option><option value="later" ${d.dstChoice==='later'?'selected':''}>選擇較晚的實際時間</option></select><small>只有當當地鐘錶時間重複出現時才會影響結果。</small></div></div>
<div id="form-error"></div><div class="form-actions"><button class="btn btn-primary" type="submit">✧ &nbsp; 開始繪製星盤 &nbsp; →</button> <button class="btn btn-muted" type="button" data-action="sample">查看示範</button></div></form>
<aside><div class="panel info-panel"><div class="sigil">✧</div><div class="eyebrow">BEFORE WE BEGIN</div><h3>一場向內的探索</h3><p class="helper">沒有正確或錯誤的星盤，每一處星象都是理解自己的另一個切角。</p><ul><li>免費分析，不需占星帳號</li><li>無須連接占星服務或資料庫</li><li>可在此裝置儲存多人的星盤</li></ul></div><div class="quiet-box" style="margin-top:14px">✦ &nbsp; 時區與座標會影響計算結果。歷史時區資料依裝置而異，早年出生資料建議另外核對。</div></aside></div>`;}
function pt(lon,r,asc){const a=(180+ A.norm(lon-asc))*Math.PI/180;return [260+Math.cos(a)*r,260-Math.sin(a)*r]}
function xy(p){return p.map(v=>v.toFixed(2)).join(',')}
function wheel(c){const asc=c.asc;let out=[`<svg id="birth-wheel" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 520 520" role="img" aria-label="${esc(c.input.name)}的十二宮星盤"><defs><style>@font-face{font-family:AtlasSymbols;src:url(data:font/woff;base64,${window.ATLAS_SYMBOL_FONT}) format('woff')}</style></defs><rect width="520" height="520" rx="20" fill="#181925"/><circle cx="260" cy="260" r="237" fill="#201f2c" stroke="#9f8664" stroke-width="1.2"/><circle cx="260" cy="260" r="199" fill="#181925" stroke="#a69071" stroke-width="1"/><circle cx="260" cy="260" r="152" fill="#1b1b2a" stroke="#6e6258" stroke-width="1"/><circle cx="260" cy="260" r="106" fill="#181925" stroke="#514951" stroke-width=".8"/>`];
for(let i=0;i<12;i++){let s=A.SIGNS[i],p1=pt(i*30,199,asc),p2=pt(i*30,237,asc),label=pt(i*30+15,218,asc);out.push(`<line x1="${p1[0]}" y1="${p1[1]}" x2="${p2[0]}" y2="${p2[1]}" stroke="#776957" stroke-width=".8"/><text x="${label[0]}" y="${label[1]}" text-anchor="middle" dominant-baseline="central" fill="#dcc497" font-size="22" font-family="AtlasSymbols,DejaVu Sans,serif">${s.glyph}</text>`)}
for(let i=0;i<12;i++){let cusp=c.houses[i].longitude,p1=pt(cusp,106,asc),p2=pt(cusp,199,asc),num=pt(cusp+15,119,asc);out.push(`<line x1="${p1[0]}" y1="${p1[1]}" x2="${p2[0]}" y2="${p2[1]}" stroke="#71645c" stroke-width=".65"/><text x="${num[0]}" y="${num[1]}" text-anchor="middle" dominant-baseline="central" fill="#b1a69f" font-size="10" font-family="Georgia,serif">${i+1}</text>`)}
for(const asp of c.aspects.slice(0,14)){const p=pt(asp.a.longitude,99,asc),q=pt(asp.b.longitude,99,asc),color=(asp.angle===90||asp.angle===180)?'#b77d84':'#809cb4';out.push(`<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="${color}" stroke-width=".8" opacity=".55"/>`)}
let placed=[];for(const p of c.planets){let level=0;for(const prev of placed)if(A.diff(p.longitude,prev.lon)<9&&level===prev.level)level++;level=Math.min(level,2);placed.push({lon:p.longitude,level});let at=pt(p.longitude,180-level*16,asc),dot=pt(p.longitude,197,asc);out.push(`<circle cx="${dot[0]}" cy="${dot[1]}" r="2" fill="#dec395"/><text x="${at[0]}" y="${at[1]}" text-anchor="middle" dominant-baseline="central" fill="#f1d8aa" font-size="16" font-family="AtlasSymbols,DejaVu Sans,serif">${p.glyph}</text>`)}
let ap=pt(asc,246,asc);out.push(`<text x="${ap[0]+4}" y="${ap[1]-6}" fill="#f0d9b3" font-size="10" font-family="Georgia,serif">ASC</text><circle cx="260" cy="260" r="3" fill="#dcc08e"/><text x="260" y="277" text-anchor="middle" fill="#a9957a" font-size="9" letter-spacing="2" font-family="Georgia,serif">ASTRAL ATLAS</text></svg>`);return out.join('')}
function threeCard(c,p,sub){let s=p.sign||A.signOf(p.longitude);return `<div class="planet-card"><div class="planet-card-art" style="background-image:url('./assets/${s.id}.webp')"></div><span class="symbol">${p.glyph}</span><div class="planet-card-text"><small>${sub}</small><strong>${s.name}</strong><p>${s.keyword}</p></div></div>`}
function analysis(c){const sun=c.planets[0],moon=c.planets[1],rising=A.signOf(c.asc);const counts={火:0,土:0,風:0,水:0};c.planets.forEach(p=>counts[p.sign.element]++);const max=Math.max(...Object.values(counts)),leading=Object.entries(counts).filter(([,v])=>v===max).map(([e])=>e).join('、');return `<div class="reading"><h3>✦ &nbsp; 核心自我｜太陽 ${sun.sign.name}</h3><p>${sun.sign.trait} 你的太陽位於第 ${sun.house} 宮，這份能量也可能在「${A.HOUSES[sun.house-1]}」的生活領域特別受到關注。</p><h3>☽ &nbsp; 情緒與安全感｜月亮 ${moon.sign.name}</h3><p>${moon.sign.trait} 當你感到疲憊時，可以回到讓自己安心的日常，覺察「${A.HOUSES[moon.house-1]}」帶來的感受。</p><h3>↗ &nbsp; 外在印象｜上升 ${rising.name}</h3><p>${rising.trait}</p><h3>✧ &nbsp; 綜合提醒</h3><p>這張星盤中的十顆行星以 ${leading} 元素較多（火 ${counts.火}・土 ${counts.土}・風 ${counts.風}・水 ${counts.水}）。${sun.sign.growth} ${moon.sign.growth}</p></div>`;}
function chart(){if(!state.chart)return form();const c=state.chart,sun=c.planets[0],moon=c.planets[1],rising={glyph:'↗',longitude:c.asc};const detail=`${esc(c.input.date)} ${esc(c.input.time)}・${esc(c.input.city==='custom'?'自訂地點':c.input.city)}・${esc(A.formatOffset(c.offsetMinutes))}・${c.input.houseSystem==='whole'?'整宮制':'等宮制'}`;return `${pagehead('YOUR NATAL CHART',`${esc(c.input.name)}的星空地圖`,detail,`<button class="btn btn-muted btn-small" data-action="edit-chart">編輯資料</button><button class="btn btn-primary btn-small" data-action="save-chart">${state.currentId?'更新紀錄':'儲存紀錄'}</button>`)}
${c.ambiguous?`<div class="quiet-box" style="margin-bottom:15px">此出生時間位於夏令時間重複時段，已選擇${c.input.dstChoice==='later'?'較晚':'較早'}的實際時間（${esc(A.formatOffset(c.offsetMinutes))}）。如與出生證明不符，請返回修改。</div>`:''}
<div class="result-top"><div class="panel chart-panel"><h2>十二宮本命星盤</h2><p>外圈為黃道星座・內圈為宮位與行星相位</p><div class="chart-wrap">${wheel(c)}</div><div class="chart-meta"><span class="chip">熱帶黃道</span><span class="chip">${c.input.houseSystem==='whole'?'整宮制':'等宮制'}</span><span class="chip">上升 ${A.signPosition(c.asc)}</span></div><div class="actions" style="justify-content:center;margin-top:18px"><button class="btn btn-muted btn-small" data-action="export-chart">↓ &nbsp; 儲存星盤圖</button><button class="btn btn-muted btn-small" data-action="export-result">↓ &nbsp; 匯出解析</button></div></div>
<div><div class="big-three">${threeCard(c,sun,'☉ &nbsp; 太陽｜核心自我')}${threeCard(c,moon,'☽ &nbsp; 月亮｜情緒世界')}${threeCard(c,rising,'↗ &nbsp; 上升｜外在印象')}</div><div class="panel result-section">${section('A GLIMPSE OF YOU','綜合解析','從太陽、月亮、上升與元素分布開始。')}${analysis(c)}<button class="btn btn-muted btn-small" data-view="trend">探索我的流年趨勢 →</button></div></div></div>
<div class="result-grid result-section"><div class="panel">${section('PLANETARY POSITIONS','行星落點','點亮性格與生活領域的不同面向。')}<div class="table-scroll"><table class="data-table"><thead><tr><th>行星</th><th>星座與度數</th><th>宮位</th><th>主題</th></tr></thead><tbody>${c.planets.map(p=>`<tr><td class="gold">${p.glyph} &nbsp; ${p.name}${p.retro?' ℞':''}</td><td>${A.signPosition(p.longitude)}</td><td>第 ${p.house} 宮</td><td>${p.theme}</td></tr>`).join('')}</tbody></table></div><p class="notice">℞ 表示相對地球視運動為逆行。行星度數為地心黃經。</p></div>
<div class="panel">${section('THE TWELVE HOUSES','十二宮位','每一宮代表生活中不同的探索場域。')}<div class="house-list">${c.houses.map(h=>`<div class="house-item"><strong>第 ${h.number} 宮・${h.sign.glyph} ${h.sign.name}</strong><span>${h.name}</span></div>`).join('')}</div></div></div>
<div class="panel result-section">${section('ASPECTS & CONNECTIONS','行星之間的對話','依本命行星夾角計算，以下依容許度由近至遠排列。')}<div class="table-scroll"><table class="data-table"><thead><tr><th>行星組合</th><th>相位</th><th>容許度</th><th>象徵主題</th></tr></thead><tbody>${c.aspects.length?c.aspects.map(a=>`<tr><td>${a.a.glyph} ${a.a.name} × ${a.b.glyph} ${a.b.name}</td><td class="gold">${a.symbol} ${a.name}</td><td>${a.orb.toFixed(1)}°</td><td>${a.tone}</td></tr>`).join(''):'<tr><td colspan="4">指定容許度內沒有主要相位。</td></tr>'}</tbody></table></div></div>
<p class="notice result-section">占星為象徵性的自我探索工具，其性格解讀與未來趨勢並無科學驗證，請勿作為醫療、投資或其他重大決策的依據。出生資料與宮位系統不同，結果也會不同。</p>`;}
function trend(){if(!state.chart)return `${pagehead('YOUR COSMIC CYCLES','流年趨勢','根據個人本命盤，觀察行星運行與本命位置之間的關係。')}<div class="panel empty"><div class="empty-icon">♃</div><h2>先從你的本命星盤開始</h2><p>建立星盤後，這裡會呈現與你本命太陽、月亮及上升點相關的流年星象。</p><div class="actions" style="justify-content:center"><button class="btn btn-primary" data-action="new-chart">繪製我的星盤 →</button></div></div>`;
const c=state.chart;return `${pagehead('YOUR COSMIC CYCLES',`${state.year} 流年星象`,`為 ${esc(c.input.name)} 計算：以木星、土星、天王星與本命太陽、月亮、上升點的主要相位，整理值得觀察的時間區間。`)}<div class="trend-intro"><div class="trend-card"><span class="glyph">♃</span><div><strong>木星・擴展</strong><p>學習、視野與成長契機</p></div></div><div class="trend-card"><span class="glyph">♄</span><div><strong>土星・建構</strong><p>責任、界線與長期累積</p></div></div><div class="trend-card"><span class="glyph">♅</span><div><strong>天王星・變化</strong><p>創新、突破與新的選擇</p></div></div></div><form class="panel year-controls" id="year-form"><div class="field"><label for="year">選擇年份</label><input id="year" type="number" min="1900" max="2050" value="${state.year}" required></div><button class="btn btn-primary" type="submit">推算這一年</button><span class="helper">以每日 UTC 00:00 取樣、相位容許度 2°；日期為近似區間。</span></form><div id="trend-content" class="result-section"><div class="panel empty" style="padding:38px"><span class="empty-icon">✧</span><p>選擇年份後，點選「推算這一年」。</p></div></div><p class="notice result-section">流年以所列三顆行星與三個本命點計算主要相位，並非完整年度占星預測；較短的相位可能因每日取樣而未顯示。趨勢用於自我反思，不代表特定事件一定發生。</p>`;}
function eventDate(ms){return new Date(ms).toISOString().slice(0,10)}
function renderEvents(events){let target=$('#trend-content');if(!target)return;target.innerHTML=section('THE YEAR AHEAD','星象時間軸',`共找到 ${events.length} 個相位區間；日期以 UTC 標示，最接近日期並非精確時刻。`)+(!events.length?'<div class="panel empty"><p>本年在所選行星與本命點之間，沒有落入 2° 容許度的主要相位區間。</p></div>':`<div class="timeline">${events.map(e=>`<article class="event"><div class="event-date"><strong>${eventDate(e.peak).slice(5).replace('-',' / ')}</strong>最接近日期<br>${eventDate(e.start)}<br>至 ${eventDate(e.end)}</div><div><h3>${e.transit.name} ${e.aspect.symbol} ${e.aspect.name} 本命${e.target.name}</h3><p>主題：${e.transit.theme}・${e.aspect.tone}｜最接近容許度 ${e.orb.toFixed(2)}°</p><p>${e.transit.tip}</p></div></article>`).join('')}</div>`);}
function signs(){return `${pagehead('THE ZODIAC COLLECTION','十二星座圖鑑','十二種原型，十二種感受與回應世界的方式。點選星座，認識每位星空守護者。')}<div class="sign-grid">${A.SIGNS.map(signCard).join('')}</div><p class="notice result-section">星座象徵可作為理解自己的起點；完整星盤還包括行星、宮位與相位。</p>`;}
function records(){return `${pagehead('YOUR PERSONAL ARCHIVE','占星紀錄',`已在這台裝置儲存 ${state.records.length} 筆星盤。清除瀏覽器資料或更換裝置可能遺失，建議定期備份。`,`<button class="btn btn-muted btn-small" data-action="import">匯入備份</button><button class="btn btn-muted btn-small" data-action="backup">匯出全部備份</button><button class="btn btn-primary btn-small" data-action="new-chart">＋ 新增星盤</button>`)}${state.records.length?`<div class="record-list">${state.records.map(r=>{let sign=A.signOf(r.chart?.planets?.[0]?.longitude||0);return `<article class="record"><span class="symbol">${sign.glyph}</span><div class="record-info"><strong>${esc(r.input.name)}</strong><small>${esc(r.input.date)} ${esc(r.input.time)}・${esc(r.input.city==='custom'?'自訂地點':r.input.city)}・太陽${sign.name}</small></div><div class="record-actions"><button class="btn btn-muted btn-small" data-action="open-record" data-id="${esc(r.id)}">查看星盤</button><button class="btn btn-muted btn-small" data-action="delete-record" data-id="${esc(r.id)}" aria-label="刪除 ${esc(r.input.name)} 的紀錄">刪除</button></div></article>`}).join('')}</div>`:`<div class="panel empty"><div class="empty-icon">☾</div><h2>把專屬星空留在這裡</h2><p>建立並儲存星盤後，你可以在這台裝置上隨時查看多人的占星紀錄。</p><div class="actions" style="justify-content:center"><button class="btn btn-primary" data-action="new-chart">新增第一張星盤 →</button></div></div>`}<p class="notice result-section">資料保存在本機瀏覽器儲存空間，不會自動同步。匯出的備份含出生資料，請妥善保管。</p>`;}
function render(){let m={home,chart,trend,signs,records};$('#app').innerHTML=(m[state.view]||home)();}
function showSign(id){const s=A.SIGNS.find(x=>x.id===id);if(!s)return;$('#modal-root').innerHTML=`<div class="modal" data-action="close-modal"><div class="panel modal-card sign-detail" role="dialog" aria-modal="true" aria-label="${s.name}"><button class="modal-close" data-action="close-modal" aria-label="關閉">×</button><img src="./assets/${s.id}.webp" alt="${s.name}神話角色插圖"><div class="sign-detail-copy"><div class="eyebrow">THE ZODIAC · ${s.id.toUpperCase()}</div><h2><span>${s.glyph}</span> ${s.name}</h2><div class="chip" style="display:inline-block">${s.element} 元素 · ${s.quality}特質</div><p>${s.trait}</p><p><strong style="color:#dfc195">給自己的提醒</strong><br>${s.growth}</p><button class="btn btn-muted btn-small" data-action="close-modal">收下這份星語</button></div></div></div>`;$('.modal-close').focus();}
function saveChart(){if(!state.chart)return;let id=state.currentId||((crypto.randomUUID&&crypto.randomUUID())||Date.now().toString(36)+Math.random().toString(36).slice(2));let record={id,createdAt:new Date().toISOString(),input:state.chart.input,chart:state.chart};let index=state.records.findIndex(r=>r.id===id);let prev=state.records.slice();if(index<0)state.records.unshift(record);else state.records[index]=record;if(persist()){state.currentId=id;toast('星盤已儲存到這台裝置');render()}else state.records=prev;}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function safeName(name){return String(name).replace(/[\\/:*?"<>|]/g,'_').slice(0,40)||'星盤'}
function exportChart(){const svg=$('#birth-wheel');if(!svg)return;const content=new XMLSerializer().serializeToString(svg);const url=URL.createObjectURL(new Blob([content],{type:'image/svg+xml;charset=utf-8'}));let img=new Image();img.onload=()=>{let canvas=document.createElement('canvas');canvas.width=1560;canvas.height=1560;let ctx=canvas.getContext('2d');ctx.fillStyle='#181925';ctx.fillRect(0,0,1560,1560);ctx.drawImage(img,0,0,1560,1560);canvas.toBlob(blob=>{if(!blob){toast('圖片匯出失敗');return}download(blob,`${safeName(state.chart.input.name)}-十二宮星盤.png`,'image/png');toast('星盤圖片已下載')},'image/png');URL.revokeObjectURL(url)};img.onerror=()=>{URL.revokeObjectURL(url);toast('圖片匯出失敗，請重試')};img.src=url;}
function resultText(c){let sun=c.planets[0],moon=c.planets[1],r=A.signOf(c.asc);let year=state.year;let ev=A.yearly(c,year);return [`星穹之書｜占星解析`,`${c.input.name}・${c.input.date} ${c.input.time}・${c.input.city==='custom'?'自訂地點':c.input.city}`,`地點 ${c.input.lat}, ${c.input.lon}；時區 ${c.input.zone}（${A.formatOffset(c.offsetMinutes)}）`,`熱帶黃道・${c.input.houseSystem==='whole'?'整宮制':'等宮制'}`,`UTC：${c.utc}`,'',`【太陽 ${sun.sign.name}】${sun.sign.trait}`,`【月亮 ${moon.sign.name}】${moon.sign.trait}`,`【上升 ${r.name}】${r.trait}`,`【建議】${sun.sign.growth} ${moon.sign.growth}`,'','【行星落點】',...c.planets.map(p=>`${p.name} ${A.signPosition(p.longitude)}・第 ${p.house} 宮${p.retro?'・逆行':''}`),'','【十二宮】',...c.houses.map(h=>`第 ${h.number} 宮 ${h.sign.name}：${h.name}`),'','【主要相位】',...c.aspects.map(a=>`${a.a.name} ${a.symbol} ${a.b.name}・${a.name}・容許度 ${a.orb.toFixed(1)}°`),'',`【${year} 年流年】（UTC 每日取樣，容許度 2°）`,...(ev.length?ev.map(e=>`${eventDate(e.start)} 至 ${eventDate(e.end)}：${e.transit.name}${e.aspect.name}本命${e.target.name}；${e.transit.tip}`):['本年未找到符合條件的主要相位。']),'','占星是象徵性的自我探索，解讀與趨勢並無科學驗證，不應作為重大決策的依據。'].join('\n');}
function backup(){if(!state.records.length){toast('目前沒有可備份的紀錄');return}download(JSON.stringify({app:'astral-atlas',version:1,exportedAt:new Date().toISOString(),records:state.records},null,2),'星穹之書-占星紀錄備份.json','application/json');toast('備份檔已下載')}
function openRecord(id){const r=state.records.find(x=>x.id===id);if(!r)return;try{state.chart=A.calculate(r.input);state.currentId=id;view('chart')}catch(e){toast('此紀錄無法開啟：'+e.message)}}
function submitBirth(form){let f=new FormData(form),input=Object.fromEntries(f.entries());input.name=input.name.trim();input.zone=input.zone.trim();if(!input.name){$('#form-error').innerHTML='<div class="message">請輸入稱呼。</div>';return}try{state.chart=A.calculate(input);view('chart');toast('你的星盤已繪製完成')}catch(e){$('#form-error').innerHTML=`<div class="message" role="alert">${esc(e.message)}</div>`;}}
function install(){if(state.install){state.install.prompt();state.install.userChoice.then(()=>{state.install=null})}else alert('安裝方式：\n\niPhone／iPad：使用 Safari 開啟後，點選「分享」→「加入主畫面」。\nAndroid：在 Chrome 選單選擇「安裝應用程式」或「加到主畫面」。\n\n首次開啟時需連線並等待資源下載完成，之後才可離線使用。');}
document.addEventListener('click',e=>{let el=e.target.closest('[data-view],[data-action]');if(!el)return;if(el.classList.contains('modal') && e.target.closest('.modal-card'))return;let v=el.dataset.view,action=el.dataset.action;if(v){e.preventDefault();view(v);return}if(!action)return;e.preventDefault();switch(action){case'new-chart':state.chart=null;state.currentId=null;view('chart');break;case'edit-chart':$('#app').innerHTML=form();break;case'sign':showSign(el.dataset.id);break;case'close-modal':$('#modal-root').innerHTML='';break;case'save-chart':saveChart();break;case'export-chart':exportChart();break;case'export-result':if(state.chart){download(resultText(state.chart),`${safeName(state.chart.input.name)}-占星解析.txt`,'text/plain;charset=utf-8');toast('解析結果已下載')}break;case'backup':backup();break;case'import':$('#backup-input').click();break;case'open-record':openRecord(el.dataset.id);break;case'delete-record':{let r=state.records.find(x=>x.id===el.dataset.id);if(r&&confirm(`確定刪除「${r.input.name}」的占星紀錄嗎？`)){let old=state.records;state.records=old.filter(x=>x.id!==r.id);if(persist()){if(state.currentId===r.id)state.currentId=null;render();toast('紀錄已刪除')}else state.records=old}break}case'sample':{state.currentId=null;const f=$('#birth-form');f.elements.name.value='星空旅人（示範）';f.elements.date.value='1990-05-20';f.elements.time.value='14:30';f.elements.city.value='台北市';f.elements.lat.value=25.033;f.elements.lon.value=121.5654;f.elements.zone.value='Asia/Taipei';submitBirth(f);break;}}});
document.addEventListener('change',e=>{if(e.target.id==='city'){const c=cities.find(x=>x[0]===e.target.value);if(c){$('#lat').value=c[2];$('#lon').value=c[3];$('#zone').value=c[4]}else{$('#lat').value='';$('#lon').value='';$('#zone').value='';$('#lat').focus()}}});
document.addEventListener('submit',e=>{if(e.target.id==='birth-form'){e.preventDefault();submitBirth(e.target)}else if(e.target.id==='year-form'){e.preventDefault();state.year=Number($('#year').value);try{$('#trend-content').innerHTML='<div class="panel empty"><p>正在計算星象，請稍候…</p></div>';setTimeout(()=>{try{state.events=A.yearly(state.chart,state.year);renderEvents(state.events)}catch(err){$('#trend-content').innerHTML=`<div class="message">${esc(err.message)}</div>`}},20)}catch(err){toast(err.message)}}});
$('#backup-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error('備份檔案過大');const data=JSON.parse(await file.text());if(data.app!=='astral-atlas'||data.version!==1||!Array.isArray(data.records)||data.records.length>500)throw new Error('備份格式不正確');let existing=new Set(state.records.map(r=>r.id)),added=[];for(let r of data.records){if(!r||typeof r.id!=='string'||r.id.length>100||!r.input||typeof r.input.name!=='string'||r.input.name.length>40||existing.has(r.id))continue;const chart=A.calculate(r.input);added.push({id:r.id,createdAt:r.createdAt,input:chart.input,chart});existing.add(r.id)}let old=state.records;state.records=[...added,...old];if(persist()){render();toast(`已匯入 ${added.length} 筆紀錄`)}else state.records=old}catch(err){toast('匯入失敗：'+err.message)}e.target.value=''});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.install=e});$('#install-button').addEventListener('click',install);
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('#modal-root').innerHTML=''});
function network(){let el=$('#network-label');if(el)el.textContent=navigator.onLine?(document.documentElement.dataset.offline==='ready'?'離線已備妥':'準備離線資源中'):'離線模式'}window.addEventListener('online',network);window.addEventListener('offline',network);network();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.active)document.documentElement.dataset.offline='ready';network();navigator.serviceWorker.ready.then(()=>{document.documentElement.dataset.offline='ready';network()})}).catch(()=>{let el=$('#network-label');if(el)el.textContent='無法啟用離線';});
else {let el=$('#network-label');if(el)el.textContent='此環境不支援離線';}
updateNav();render();
})();
